    function btn(txt, tip, fn) { var b = document.createElement('button'); b.className = 'sm'; b.textContent = txt; b.title = tip; b.addEventListener('click', fn); row.appendChild(b); return b; }
    btn('#' + (i + 1), t('recGo'), function () { rcGo(i); });
